// Before: one query per order for the customer (N + 1 round trips)
List<OrderView> slow(List<Order> orders) {
    List<OrderView> out = new ArrayList<>();
    for (Order o : orders) {
        Customer c = customerRepository.findById(o.customerId()).orElseThrow();
        out.add(new OrderView(o.id(), c.name(), o.total()));
    }
    return out;
}

// After: one batched query, joined in memory by id
List<OrderView> batched(List<Order> orders) {
    Set<String> ids = orders.stream().map(Order::customerId).collect(Collectors.toSet());
    Map<String, Customer> byId = customerRepository.findAllById(ids).stream()
            .collect(Collectors.toMap(Customer::id, Function.identity()));
    return orders.stream()
            .map(o -> new OrderView(o.id(), byId.get(o.customerId()).name(), o.total()))
            .toList();
}

